class Solution:
    def maxAmount(self, initialCurrency: str, pairs1: List[List[str]], rates1: List[float], pairs2: List[List[str]], rates2: List[float]) -> float:
        def build(pairs, rates, rev=False):
            g = {}
            for (a, b), r in zip(pairs, rates):
                if rev:
                    a, b = b, a
                g.setdefault(a, []).append((b, r))
                g.setdefault(b, []).append((a, 1.0 / r))
            return g
        def best(g, src):
            d = {src: 1.0}
            changed = True
            while changed:
                changed = False
                for u in list(d):
                    for v, r in g.get(u, []):
                        nd = d[u] * r
                        if v not in d or nd > d[v]:
                            d[v] = nd
                            changed = True
            return d
        d1 = best(build(pairs1, rates1), initialCurrency)
        back = best(build(pairs2, rates2, rev=True), initialCurrency)
        return max(d1[c] * back.get(c, 0.0) for c in d1)

