class Solution {
    unordered_map<string, vector<pair<string,double>>> build(vector<vector<string>>& pairs,
                                                             vector<double>& rates, bool rev) {
        unordered_map<string, vector<pair<string,double>>> g;
        for (int i = 0; i < (int)pairs.size(); i++) {
            string a = pairs[i][0], b = pairs[i][1];
            double r = rates[i];
            if (rev) swap(a, b);
            g[a].push_back({b, r});
            g[b].push_back({a, 1.0 / r});
        }
        return g;
    }
    unordered_map<string,double> best(unordered_map<string, vector<pair<string,double>>>& g,
                                      const string& src) {
        unordered_map<string,double> d{{src, 1.0}};
        bool changed = true;
        while (changed) {
            changed = false;
            for (auto& kv : d) {
                for (auto& [v, r] : g[kv.first]) {
                    double nd = kv.second * r;
                    if (!d.count(v) || nd > d[v]) { d[v] = nd; changed = true; }
                }
            }
        }
        return d;
    }
public:
    double maxAmount(string initialCurrency, vector<vector<string>>& pairs1,
                     vector<double>& rates1, vector<vector<string>>& pairs2,
                     vector<double>& rates2) {
        auto d1 = best(build(pairs1, rates1, false), initialCurrency);
        auto back = best(build(pairs2, rates2, true), initialCurrency);
        double ans = 0;
        for (auto& kv : d1) {
            auto it = back.find(kv.first);
            ans = max(ans, kv.second * (it == back.end() ? 0.0 : it->second));
        }
        return ans;
    }
};

