class Solution {
    private Map<String, List<Object[]>> build(List<List<String>> pairs, double[] rates, boolean rev) {
        Map<String, List<Object[]>> g = new HashMap<>();
        for (int i = 0; i < pairs.size(); i++) {
            String a = pairs.get(i).get(0), b = pairs.get(i).get(1);
            double r = rates[i];
            if (rev) { String t = a; a = b; b = t; }
            g.computeIfAbsent(a, k -> new ArrayList<>()).add(new Object[]{b, r});
            g.computeIfAbsent(b, k -> new ArrayList<>()).add(new Object[]{a, 1.0 / r});
        }
        return g;
    }
    private Map<String, Double> best(Map<String, List<Object[]>> g, String src) {
        Map<String, Double> d = new HashMap<>();
        d.put(src, 1.0);
        boolean changed = true;
        while (changed) {
            changed = false;
            for (String u : new ArrayList<>(d.keySet()))
                for (Object[] e : g.getOrDefault(u, Collections.emptyList())) {
                    String v = (String)e[0];
                    double nd = d.get(u) * (Double)e[1];
                    if (!d.containsKey(v) || nd > d.get(v)) { d.put(v, nd); changed = true; }
                }
        }
        return d;
    }
    public double maxAmount(String initialCurrency, List<List<String>> pairs1, double[] rates1,
                            List<List<String>> pairs2, double[] rates2) {
        Map<String, Double> d1 = best(build(pairs1, rates1, false), initialCurrency);
        Map<String, Double> back = best(build(pairs2, rates2, true), initialCurrency);
        double ans = 0;
        for (String c : d1.keySet())
            ans = Math.max(ans, d1.get(c) * back.getOrDefault(c, 0.0));
        return ans;
    }
}

