class Solution:
    def maxAmount(self, initialCurrency, pairs1, rates1, pairs2, rates2):
        from functools import lru_cache
        gin, gout = {}, {}
        for (a, b), r in zip(pairs1, rates1):
            gin.setdefault(b, []).append((a, r))
        for (a, b), r in zip(pairs2, rates2):
            gout.setdefault(a, []).append((b, r))
        @lru_cache(None)
        def fwd(c):
            best = 1.0 if c == initialCurrency else 0.0
            for a, r in gin.get(c, []):
                best = max(best, fwd(a) * r)
            return best
        @lru_cache(None)
        def bwd(c):
            best = 1.0 if c == initialCurrency else 0.0
            for b, r in gout.get(c, []):
                best = max(best, bwd(b) * r)
            return best
        curs = set(fwd.__wrapped__.__defaults__ or []) if False else set()
        for (a, b), _ in zip(pairs1, rates1):
            curs.update((a, b))
        for (a, b), _ in zip(pairs2, rates2):
            curs.update((a, b))
        curs.add(initialCurrency)
        return max(fwd(c) * bwd(c) for c in curs)

