    unordered_map<string,double> mf, mb;
    string init;
    double fwd(const string& c) {
        if (mf.count(c)) return mf[c];
        double best = (c == init) ? 1.0 : 0.0;
        for (auto& [a, r] : gin[c]) best = max(best, fwd(a) * r);
        return mf[c] = best;
    }
    double bwd(const string& c) {
        if (mb.count(c)) return mb[c];
        double best = (c == init) ? 1.0 : 0.0;
        for (auto& [b, r] : gout[c]) best = max(best, bwd(b) * r);
        return mb[c] = best;
    }
public:
