class Solution {
    Map<String, List<Object[]>> gin = new HashMap<>(), gout = new HashMap<>();
    Map<String, Double> mf = new HashMap<>(), mb = new HashMap<>();
    String init;
    double fwd(String c) {
        if (mf.containsKey(c)) return mf.get(c);
        double best = c.equals(init) ? 1.0 : 0.0;
        for (Object[] e : gin.getOrDefault(c, Collections.emptyList()))
            best = Math.max(best, fwd((String)e[0]) * (Double)e[1]);
        mf.put(c, best);
        return best;
    }
    double bwd(String c) {
        if (mb.containsKey(c)) return mb.get(c);
        double best = c.equals(init) ? 1.0 : 0.0;
        for (Object[] e : gout.getOrDefault(c, Collections.emptyList()))
            best = Math.max(best, bwd((String)e[0]) * (Double)e[1]);
        mb.put(c, best);
        return best;
    }
    public double maxAmount(String initialCurrency, List<List<String>> pairs1, double[] rates1,
                            List<List<String>> pairs2, double[] rates2) {
        init = initialCurrency;
        for (int i = 0; i < pairs1.size(); i++)
            gin.computeIfAbsent(pairs1.get(i).get(1), k -> new ArrayList<>())
               .add(new Object[]{pairs1.get(i).get(0), rates1[i]});
        for (int i = 0; i < pairs2.size(); i++)
            gout.computeIfAbsent(pairs2.get(i).get(0), k -> new ArrayList<>())
               .add(new Object[]{pairs2.get(i).get(1), rates2[i]});
        Set<String> curs = new HashSet<>();
        curs.add(initialCurrency);
        for (List<String> p : pairs1) { curs.add(p.get(0)); curs.add(p.get(1)); }
        for (List<String> p : pairs2) { curs.add(p.get(0)); curs.add(p.get(1)); }
        double ans = 0;
        for (String c : curs) ans = Math.max(ans, fwd(c) * bwd(c));
        return ans;
    }
}

