var maxAmount = function(initialCurrency, pairs1, rates1, pairs2, rates2) {
    const gin = {}, gout = {};
    pairs1.forEach(([a, b], i) => (gin[b] = gin[b] || []).push([a, rates1[i]]));
    pairs2.forEach(([a, b], i) => (gout[a] = gout[a] || []).push([b, rates2[i]]));
    const mf = new Map(), mb = new Map();
    const fwd = (c) => {
        if (mf.has(c)) return mf.get(c);
        let best = c === initialCurrency ? 1.0 : 0.0;
        for (const [a, r] of (gin[c] || [])) best = Math.max(best, fwd(a) * r);
        mf.set(c, best);
        return best;
    };
    const bwd = (c) => {
        if (mb.has(c)) return mb.get(c);
        let best = c === initialCurrency ? 1.0 : 0.0;
        for (const [b, r] of (gout[c] || [])) best = Math.max(best, bwd(b) * r);
        mb.set(c, best);
        return best;
    };
    const curs = new Set([initialCurrency]);
    pairs1.forEach(([a, b]) => { curs.add(a); curs.add(b); });
    pairs2.forEach(([a, b]) => { curs.add(a); curs.add(b); });
    let ans = 0;
    for (const c of curs) ans = Math.max(ans, fwd(c) * bwd(c));
    return ans;
};
